scene.ondrop=event=>{event.preventDefault();nodes.forEach(n=>n.classList.remove('drop-target'));const at=pointAt(event),node=event.target.closest('.item'),b=node&&byId(node.dataset.id),part=event.dataTransfer.getData('application/grove-part'),id=event.dataTransfer.getData('application/grove-collection'),field=event.dataTransfer.getData('application/grove-field'),screenId=event.dataTransfer.getData('application/grove-screen');if(part){const fresh=add(part,at);if(b?.part==='frame'){fresh.parent=b.id;b.rect.w=Math.max(b.rect.w,fresh.rect.x+fresh.rect.w-b.rect.x+12);b.rect.h=Math.max(b.rect.h,fresh.rect.y+fresh.rect.h-b.rect.y+12);save(b);save(fresh);render();}return;}if(field){const ref=JSON.parse(field);dropField(b||add('text',at),ref,event.target.closest('[data-channel]')?.dataset.channel);return;}if(screenId&&b){bindScreen(b,screenId);return;}if(id){if(b)bindCollection(b,id);else ask('Show '+nativeName(id)+' as the most useful view',at,{collection:id});}};
