function duplicateParts(root){checkpoint('Duplicate composition');const originals=active().filter(b=>b.id===root.id||ancestorIds(b).includes(root.id)),ids=new Map(originals.map(b=>[b.id,uid()]));for(const original of originals){const b=clone(original);b.id=ids.get(original.id);b.parent=ids.get(original.parent)||'';b.sourceId=ids.get(original.sourceId)||original.sourceId;b.rect.x+=28;b.rect.y+=28;b.revision=0;b.content=b.content.map(c=>({...c,id:uid()}));blocks.push(b);save(b);}render();select(ids.get(root.id));}
function decisionKey(prompt,context){return JSON.stringify([prompt,context,active().map(b=>[b.id,b.part,b.nativeCollection,b.sourceId]),nativeState.nodes.map(n=>[n.id,n.expected])]);}
async function ask(prompt,position=null,context={}){prompt=prompt.trim();if(!prompt)return;const key=decisionKey(prompt,context),epoch=++requestEpoch;clearTimeout(promptTimer);$('#prompt').value=prompt;$('#suggestion').hidden=false;$('#suggestion').replaceChildren(element('span','Choosing among available components and bindings…','proposal-sentence'));const basis=selected;try{let result=choices.get(key);if(result)result={...result,cached:true,model_calls:0};else{if(!ai)throw Error('JEV is off. No stored decision matches this request; your canvas is unchanged');$('#prompt-state').textContent='choosing…';await queue;const response=await fetch('/api/decide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,selected:basis,...context})});result=await response.json();if(!response.ok)throw Error(result.error||'Decision unavailable');choices.set(key,result);if(choices.size>60)choices.delete(choices.keys().next().value);localStorage.setItem(CHOICE_KEY,JSON.stringify([...choices]));modelCalls+=result.model_calls||0;}if(epoch!==requestEpoch)return;receipts.push(result);lastDecision=result;$('#prompt-state').textContent=result.cached?'cached':Math.round(result.total_ms||result.elapsed_ms)+' ms';log(prompt,'jev','Request · '+(result.cached?'cached':result.model||'Jev'));showDecision(result,epoch,position);}catch(error){if(epoch!==requestEpoch)return;$('#prompt-state').textContent='needs attention';$('#suggestion').replaceChildren(element('span',error.message,'proposal-sentence error'));report(error);}}
function showDecision(result,epoch,position){const tray=$('#suggestion');tray.hidden=false;tray.replaceChildren();const choice=result.choice;tray.append(element('span',choice.label,'proposal-sentence'));const metadata=element('span',result.cached?'cached · 0 calls':Math.round(result.elapsed_ms)+' ms · '+(result.output_bytes||0)+' B','proposal-meta');tray.append(metadata);const accept=element('button',choice.action.op==='question'?'Keep question':'Apply','primary');accept.onclick=async()=>{if(epoch!==requestEpoch)return;accept.disabled=true;try{await applyChoice(choice,position);tray.hidden=true;$('#prompt').value='';log(choice.label,'jev',result.cached?'Stored choice':(result.model||'Jev')+' · '+Math.round(result.elapsed_ms)+' ms');}catch(error){accept.disabled=false;report(error);}};tray.append(accept);const alternatives=selectControl([['','Not that…'],...(result.alternatives||[]).filter(x=>x.id!==choice.id).map(x=>[x.id,x.label])],'',id=>{const other=result.alternatives.find(x=>x.id===id);if(other)showDecision({...result,choice:other},epoch,position);});alternatives.setAttribute('aria-label','Alternative interpretation');tray.append(alternatives);const close=element('button','×');close.setAttribute('aria-label','Dismiss suggestion');close.onclick=()=>{requestEpoch++;tray.hidden=true;};tray.append(close);}
async function applyChoice(choice,position){const a=choice.action;if(a.op==='question'){say('Missing capability retained as a question; nothing fabricated.',true);return;}if(a.collection){await refreshNative();const n=nativeNode(a.collection);if(!n||a.fields&&!a.fields.every(f=>n.properties.some(p=>p.label===f)))throw Error('The native shape changed. Choose again.');}if(a.op==='component'){const def=byId(a.definition);if(!def||def.componentDefinition?.revision!==a.revision)throw Error('That component revision changed');instantiate(def);return;}if(a.op==='form'){createForm(a.collection,null,position);return;}if(a.op==='edit_form'){const source=byId(a.sourceId);if(!source||collection(source)!==a.collection)throw Error('The selection source changed');createForm(a.collection,a.sourceId,position);return;}if(a.op==='shape_share'){const b=byId(a.target);if(!b)throw Error('Target shape missing');b.nativeCollection=a.collection;b.aggregateBinding={formula:'share',field:a.field,equals:a.equals};save(b);render();return;}if(!['place','view'].includes(a.op))throw Error('Unknown prepared choice');if(!catalog.some(c=>c[0]===a.part)&&!['rectangle','circle','label'].includes(a.part))throw Error('This component is not installed');const b=add(a.part,position);if(a.collection){b.nativeCollection=a.collection;setTitle(b,nativeName(a.collection));}for(const key of ['groupField','field','formula','labelField'])if(a[key]!==undefined)b[key]=a[key];if(a.part==='text'){const quoted=$('#prompt').value.match(/["“](.+?)["”]/);if(quoted)b.notes=quoted[1];}save(b);render();showProperties();reveal(b);}
$('#prompt-bar').onsubmit=e=>{e.preventDefault();ask($('#prompt').value);};$('#prompt').oninput=()=>{clearTimeout(promptTimer);requestEpoch++;$('#prompt-state').textContent=ai?'…':'off';if(ai&&$('#prompt').value.trim().length>7)promptTimer=setTimeout(()=>ask($('#prompt').value),1000);};
$('#ai').onclick=()=>{ai=!ai;$('#ai').setAttribute('aria-pressed',String(ai));$('#ai').lastChild.textContent=ai?'jev · decisions':'jev · off';say(ai?'JEV decisions enabled':'JEV off · established interactions still work');};
function setZoom(value){zoom=Math.max(.4,Math.min(1.6,value));scene.style.transform='scale('+zoom+')';$('#zoom').textContent=Math.round(zoom*100)+'%';$('#property-popover').hidden=true;}
$('#zoom-in').onclick=()=>setZoom(zoom+.1);$('#zoom-out').onclick=()=>setZoom(zoom-.1);$('#library-toggle').onclick=()=>document.body.classList.toggle('show-library');$('#decisions-toggle').onclick=()=>document.body.classList.toggle('show-decisions');$('#new-material').onclick=()=>openMaterial();$('#refresh').onclick=()=>refreshNative().then(()=>say('Native material refreshed')).catch(report);$('#delay').onclick=()=>{delay=delay?0:2000;$('#delay').textContent=delay?'Network +2 s':'Network normal';};$('#scene-name').oninput=draft;
$('#fit').onclick=()=>{checkpoint('Tidy scene');const roots=active().filter(b=>!b.parent||!active().some(c=>c.id===b.parent));let x=24,y=28,rowHeight=0;const width=Math.max(440,viewport.clientWidth/zoom-24);for(const b of roots){if(x+b.rect.w>width&&x>24){x=24;y+=rowHeight+28;rowHeight=0;}const dx=x-b.rect.x,dy=y-b.rect.y;b.rect.x=x;b.rect.y=y;for(const child of active().filter(c=>ancestorIds(c).includes(b.id))){child.rect.x+=dx;child.rect.y+=dy;save(child);}nodes.get(b.id)?.classList.add('fit-motion');save(b);x+=b.rect.w+24;rowHeight=Math.max(rowHeight,b.rect.h);}render();$('#property-popover').hidden=true;log('Tidied layout, preserving content and bindings','local','Zero model calls · undo restores placements');};
$('#undo').onclick=()=>{const previous=undoStack.pop();if(!previous){say('No layout change to undo in this session');return;}const held=clone(blocks);blocks=clone(previous.blocks);for(const old of held)if(!byId(old.id))blocks.push({...old,archived:true});for(const b of blocks){b.revision=committed.get(b.id)?.revision||0;save(b);}selected=null;render();$('#property-popover').hidden=true;say('Undid '+previous.reason+' · native records are not deleted');};
for(const[kind,icon,label]of catalog){const button=element('button');button.append(element('span',icon),document.createTextNode(label));button.draggable=true;button.ondragstart=e=>e.dataTransfer.setData('application/grove-part',kind);button.onclick=()=>{add(kind);document.body.classList.remove('show-library');};$('#catalog').append(button);}for(const[kind,icon,label]of [['select','↖','Select'],['rectangle','▭','Rectangle'],['circle','◯','Circle'],['line','╱','Line'],['label','T','Label'],['frame','⊞','Frame'],['input','▤','Input']]){const button=element('button',icon);button.title=label;button.setAttribute('aria-label',label+' tool');button.onclick=()=>{if(['frame','input'].includes(kind))add(kind);else tool=kind;$('#tool-label').textContent=label;$('#property-popover').hidden=true;document.body.classList.remove('show-library');};$('#atoms').append(button);}for(const text of ['Show my data as a board','Make an input form','Add a chart']){const button=element('button',text);button.onclick=()=>ask(text);$('#starters').append(button);}
function makerMode(id){maker=id;selected=null;tool='select';$('#maker-bar').hidden=!id;document.body.classList.toggle('in-maker',!!id);$('#canvas-context').textContent=id?'Component maker':'Your scene';$('#maker-name').value=id?title(byId(id)):'';$('#property-popover').hidden=true;render();renderStateFields();viewport.scrollLeft=0;viewport.scrollTop=0;}
$('#maker-open').onclick=()=>{let root=blocks.find(b=>b.makerRoot&&!b.archived);if(!root){root=newBlock('frame',30,30);root.makerRoot=true;root.workspace=root.id;root.rect.w=580;root.rect.h=350;setTitle(root,'Untitled component');blocks.push(root);save(root);}makerMode(root.id);document.body.classList.remove('show-library');};$('#maker-back').onclick=()=>makerMode(null);$('#home').onclick=()=>makerMode(null);$('#maker-name').oninput=()=>{const b=byId(maker);setTitle(b,$('#maker-name').value);save(b);renderItem(b);};$('#maker-preview').onclick=()=>{preview=!preview;$('#maker-preview').textContent=preview?'Stop preview':'Preview';say(preview?'Use the component’s mapped controls':'Arrange and map component parts');};
function renderStateFields(){const host=$('#state-fields');host.replaceChildren();if(!maker)return;const root=byId(maker);for(const field of root.stateFields||[]){const chip=element('button',field,'field-chip');host.append(chip);}const input=element('input');input.placeholder='+ state field';input.setAttribute('aria-label','Component state field');input.onkeydown=e=>{if(e.key==='Enter'&&input.value.trim()){root.stateFields=[...new Set([...(root.stateFields||[]),input.value.trim()])];save(root);renderStateFields();}};host.append(input);}
$('#maker-save').onclick=()=>{const root=byId(maker);if(!root)return;setTitle(root,$('#maker-name').value.trim()||'Untitled component');save(root);const parts=clone(active()),definition=newBlock('frame',0,0);definition.workspace='library';setTitle(definition,title(root));definition.componentDefinition={revision:1,root:root.id,parts,contract:{slots:parts.map(b=>({id:b.id,parent:b.parent,name:title(b)})),inputs:parts.flatMap(b=>Object.entries(b.properties||{}).filter(([,p])=>p.mode==='source').map(([channel,p])=>({part:b.id,channel,field:p.field,shape:'unresolved'}))),params:['selection'],outputs:[],intents:parts.flatMap(b=>Object.entries(b.properties||{}).filter(([,p])=>p.mode==='input').map(([channel,p])=>({part:b.id,channel,field:p.field,destination:collection(b)}))),labels:parts.map(b=>({id:b.id,text:title(b)})),completion:[]},coverage:'Editable composition; native structural contract compilation remains pending'};blocks.push(definition);save(definition);makerMode(null);log('Saved '+title(definition)+' in the component palette','local','Composition revision 1 · unresolved types remain holes');};
function renderSaved(){const host=$('#saved-components');host.replaceChildren();for(const b of blocks.filter(b=>b.componentDefinition&&!b.archived)){const button=element('button',title(b)+' · v'+b.componentDefinition.revision,'saved-component');button.onclick=()=>instantiate(b);host.append(button);}}
function instantiate(definition){checkpoint('Instantiate component');const stored=definition.componentDefinition,parts=stored.parts,root=parts.find(b=>b.id===stored.root),ids=new Map(parts.map(b=>[b.id,uid()])),at=placeFor('frame');for(const old of parts){const b=clone(old);b.id=ids.get(old.id);b.parent=ids.get(old.parent)||maker||'';b.sourceId=ids.get(old.sourceId)||old.sourceId;b.workspace=maker||undefined;b.revision=0;b.rect.x=at.x+old.rect.x-root.rect.x;b.rect.y=at.y+old.rect.y-root.rect.y;b.content=b.content.map(c=>({...c,id:uid()}));b.componentRevision={subject:definition.id,revision:stored.revision};delete b.makerRoot;blocks.push(b);save(b);}render();select(ids.get(root.id));reveal(byId(ids.get(root.id)));}
function filesDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('grove-authoring-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function storeFile(id,file){const db=await filesDB();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}
async function loadFile(id){const db=await filesDB();const result=await new Promise(resolve=>{const request=db.transaction('files').objectStore('files').get(id);request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);});db.close();return result;}
async function browse(subject='/0x11/app'){try{const result=await nativeCall('native/discover',{subject});const host=$('#native-browser');host.replaceChildren();if(subject!=='/0x11/app'){const up=element('button','‹ Parent');up.onclick=()=>browse(subject.slice(0,subject.lastIndexOf('/')));host.append(up);}for(const child of result.children||[]){const button=element('button',child.label||child.subject.split('/').at(-1));button.title=child.subject;button.onclick=()=>browse(child.subject);button.ondblclick=()=>placeNative(child.subject);host.append(button);}const place=element('button','Place native view');place.onclick=()=>placeNative(subject);host.append(place);}catch(error){report(error);}}
async function placeNative(subject){const frame=await nativeCall('native/frame',{subject,viewport:[]}),b=add('card');b.part='native';b.kind='material';b.source={subject,revision:frame.basis.owner.case};b.rect.w=430;b.rect.h=280;setTitle(b,subject.split('/').at(-1));nativeFrames.set(b.id,frame);save(b);render();}
async function loadNativeFrame(b){try{nativeFrames.set(b.id,await nativeCall('native/frame',{subject:b.source.subject,viewport:[]}));renderItem(b);}catch(error){report(error);}}
window.addEventListener('keydown',event=>{if(event.target.matches('input,textarea,select,[contenteditable]'))return;if(event.key==='Escape'){tool='select';pointing=null;$('#property-popover').hidden=true;$('#suggestion').hidden=true;}if((event.metaKey||event.ctrlKey)&&event.key==='z'){event.preventDefault();$('#undo').click();}if((event.key==='Delete'||event.key==='Backspace')&&selected){event.preventDefault();checkpoint('Remove item');const b=byId(selected);b.archived=true;save(b);select(null);render();}});
async function start(){try{await fetch('/connect',{method:'POST'});const state=await nativeCall('fit/read');blocks=state.blocks;for(const b of blocks){committed.set(b.id,clone(b));b.mapping=b.mapping||{};b.properties=b.properties||{};b.items=b.items||[];}connected=true;if(stored?.blocks)for(const b of stored.blocks){const existing=byId(b.id);if(!existing&&b.revision===0){blocks.push(b);dirty.add(b.id);}else if(existing&&b.revision===existing.revision&&JSON.stringify(existing)!==JSON.stringify(b)){Object.assign(existing,b);dirty.add(b.id);}}$('#scene-name').value=stored?.name||'Untitled scene';render();await flush();await refreshNative();browse();for(const b of blocks){if(b.file){const file=await loadFile(b.id);if(file)mediaURLs.set(b.id,URL.createObjectURL(file));}if(b.part==='native')loadNativeFrame(b);}render();$('#save-state').textContent='Saved in Shrine';log('Scene restored with native identities','local','Existing work retained · no model');nativeRefreshTimer=setInterval(()=>{if(!document.hidden&&!drag)refreshNative().catch(()=>{});},5000);}catch(error){blocks=stored?.blocks||[];render();report(error);$('#save-state').textContent='Draft retained';}}
window.groveEvidence=()=>({modelCalls,largeModelCalls:0,receipts:clone(receipts),localPaintOpportunityMs:[...samples],pendingSaves:dirty.size,blocks:active().length});
